enum Forma {
    Cerchio(f64),
    Rettangolo { base: f64, altezza: f64 },
    Punto,
}

fn area(f: &Forma) -> f64 {
    match f {
        Forma::Cerchio(r) => std::f64::consts::PI * r * r,
        Forma::Rettangolo { base, altezza } => base * altezza,
        Forma::Punto => 0.0,
    }
}

