def ricerca_binaria(lista, obiettivo):
    basso, alto = 0, len(lista) - 1
    while basso <= alto:
        medio = (basso + alto) // 2
        if lista[medio] == obiettivo:
            return medio
        if lista[medio] < obiettivo:
            basso = medio + 1
        else:
            alto = medio - 1
    return -1

